-- G logical cards: one physical entity and payment, two independent ordinary card stacks.
create or replace function ml_private.p3g_close_card(s jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare cards jsonb:=s#>'{cardStack,stack}';c jsonb:=cards->-1;parent jsonb:=cards->-2;idx text:=(jsonb_array_length(cards)-2)::text;actor integer:=(c->>'responseActor')::int;begin
 perform ml_private.need(c->'counter'='null'::jsonb,'反制尚未结束');if c->'responseTo'<>'null'::jsonb then perform ml_private.need(parent->'serial'=c->'responseTo','响应父牌已过期');if c->>'countered'<>'true' then if c#>'{stage4,counter}' is not null then if c#>>'{stage4,counterEffective}'='true' then cards:=jsonb_set(cards,array[idx,'countered'],'true');end if;else if not(parent->'cancelled' @> jsonb_build_array(actor)) then cards:=jsonb_set(cards,array[idx,'cancelled'],(parent->'cancelled')||jsonb_build_array(actor));end if;if c->>'definition'='basic-002' then cards:=jsonb_set(cards,array[idx,'elbows'],(parent->'elbows')||jsonb_build_array(actor));end if;end if;end if;end if;
 s:=jsonb_set(s,'{cardStack,stack}',cards-(jsonb_array_length(cards)-1));if c#>>'{g,copy}'<>'1' then s:=jsonb_set(s,'{resolving}',(s->'resolving')-(c->>'card'));s:=ml_private.exercise_discard(s,jsonb_build_array(c->'card'));end if;return s||jsonb_build_object('_closed',c);end $$;
create or replace function ml_private.p3g_repeat_legal(s jsonb,c jsonb,target integer) returns boolean language plpgsql stable set search_path=pg_catalog,ml_private as $$declare a integer:=(c->>'actor')::int;definition text:=c->>'definition';d jsonb:=ml_private.rule_card(s,definition);begin
 if definition='basic-037' then return jsonb_array_length(ml_private.stage3_revival_cells(s,target,(s#>>'{classic,farmClosed}')::boolean))>0;end if;
 if not ml_private.stage4_on_board(s,target) or not ml_private.p3g_card_target_allowed(s,a,target,definition) or c->'responseTo'<>'null'::jsonb then return false;end if;
 if definition='basic-002' then return ml_private.region_at(s->>'version',s#>>array['players',target::text,'cell'])=ml_private.region_at(s->>'version',s#>>array['players',a::text,'cell']) and not ml_private.stage4_single_protected(s,a,target);end if;
 if d->>'type'='attack' then return ml_private.targets(s,a,definition) @> jsonb_build_array(target);end if;
 if definition='basic-016' then return target<>a and not ml_private.stage3_mount_blocked(s,a) and ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,s#>>array['players',target::text,'cell'],jsonb_build_array(a,target)) and ml_private.stage3_empty_entry(ml_private.stage3_board(s),target,s#>>array['players',a::text,'cell'],jsonb_build_array(a,target));end if;
 if definition='basic-041' then return ml_private.stage3_assam_targets(s,a) @> jsonb_build_array(target);end if;if definition='basic-040' then return s#>>array['players',target::text,'faction']='帝汶家族';end if;
 if definition in ('basic-007','basic-018','basic-019','basic-022','basic-029','basic-030','basic-035','basic-036','basic-021','basic-024') then return ml_private.stage4_targets(s,a,definition) @> jsonb_build_array(target);end if;
 if definition='basic-026' then return target<>a and (s->>'mode'='ffa' or s#>array['players',target::text,'team']<>s#>array['players',a::text,'team']);end if;
 return not(coalesce(d->>'group','false')='true' and s#>>array['players',target::text,'character']='character-027' and jsonb_array_length(s#>array['players',target::text,'hand'])=1);end $$;
create or replace function ml_private.p3g_dual_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare firstn jsonb:=s#>'{cardStack,stack,-1}';parent jsonb;c jsonb;d jsonb;a integer;idx text;targets jsonb;original_queue jsonb;begin
 if not ml_private.p3g_enabled(s) then return s||jsonb_build_object('_gDualHandled',false);end if;
 if t->>'action'='cleanup' and firstn#>>'{g,copy}'='1' and (not(t ? 'serial') or t->'serial'=firstn->'serial') then s:=ml_private.p3g_close_card(s);firstn:=s->'_closed';s:=s-'_closed';original_queue:=s->'queue';s:=jsonb_set(s,'{queue}','[]');s:=ml_private.p3c_food_tasks(s,firstn);s:=jsonb_set(s,'{queue}',(s->'queue')||jsonb_build_array(ml_private.stage3_task('g-repeat-card',jsonb_build_object('data',firstn)))||original_queue);if firstn->>'installed'='true' then s:=jsonb_set(s,'{discard}',(s->'discard')-(firstn->>'card'));end if;parent:=s#>'{cardStack,stack,-1}';s:=s||jsonb_build_object('phase','resolving','attack',case when parent is null then null else jsonb_build_object('actor',parent->'actor','card',parent->'card','targets',parent->'targets','cancelled',parent->'cancelled','elbows',parent->'elbows') end);return s||jsonb_build_object('_gDualHandled',true);end if;
 if t->>'action'<>'g-repeat-card' then return s||jsonb_build_object('_gDualHandled',false);end if;firstn:=t->'data';a:=(firstn->>'actor')::int;parent:=s#>'{cardStack,stack,-1}';
 if not ml_private.stage4_on_board(s,a) or firstn->'responseTo'<>'null'::jsonb and (parent is null or parent->'serial'<>firstn->'responseTo' or not ml_private.p3g_card_target_allowed(s,a,case when firstn->>'definition'='basic-001' then a else (parent->>'actor')::int end,firstn->>'definition')) then s:=jsonb_set(s,'{resolving}',(s->'resolving')-(firstn->>'card'));s:=ml_private.exercise_discard(s,jsonb_build_array(firstn->'card'));s:=ml_private.emit(s,'play','S'||(a+1)||' 质数第二份失效：使用者或父牌已失效');if jsonb_array_length(s#>'{cardStack,stack}')=0 then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then if ml_private.stage3_alive(s,(s->>'active')::int) then s:=jsonb_set(s,'{phase}','"action"');else s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','next')));end if;end if;end if;return s||jsonb_build_object('_gDualHandled',true);end if;
 d:=ml_private.rule_card(s,firstn->>'definition');select coalesce(jsonb_agg(v order by n),'[]') into targets from jsonb_array_elements(firstn#>'{g,targets}') with ordinality q(v,n) where ml_private.p3g_repeat_legal(s,firstn,(v#>>'{}')::int);
 s:=ml_private.stage3_begin_card(s,a,firstn->>'card',firstn->>'definition',targets,firstn->'effect',at,(firstn->>'responseTo')::int);idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;c:=s#>array['cardStack','stack',idx];c:=jsonb_set(c,'{g,copy}','2');if firstn#>'{g,replacements}' is not null then c:=jsonb_set(c,'{g,replacements}',firstn#>'{g,replacements}');end if;if firstn->>'definition'='basic-017' and firstn->>'countered'<>'true' then c:=jsonb_set(c,'{g,firstSucceeded}','true');end if;
 if firstn ? 'converted' then c:=c||jsonb_build_object('converted',firstn->'converted');end if;if firstn ? 'pushDirection' then c:=c||jsonb_build_object('pushDirection',firstn->'pushDirection');end if;if firstn ? 'replacement' then c:=c||jsonb_build_object('replacement',firstn->'replacement');end if;
 select coalesce(jsonb_agg(p->'seat' order by n),'[]') into targets from jsonb_array_elements(s->'players') with ordinality q(p,n) where not ml_private.stage4_location_effect(s,(p->>'seat')::int,firstn->>'definition');c:=c||jsonb_build_object('stage4',coalesce(firstn->'stage4','{}')-array['counterEffective','counterOffered','guessDie','officeExempt']||jsonb_build_object('officeExempt',targets));s:=jsonb_set(s,array['cardStack','stack',idx],c);
 if d->>'type'='attack' or c->>'definition'='basic-002' and c->'responseTo'='null'::jsonb then s:=jsonb_set(s,array['players',a::text,'attacks'],to_jsonb((s#>>array['players',a::text,'attacks'])::int+1));end if;s:=ml_private.emit(s,'play','S'||(a+1)||' 质数第二份'||(d->>'name')||'，不重复支付费用');s:=jsonb_set(s,'{phase}','"resolving"');s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('counter',jsonb_build_object('serial',c->'serial')),ml_private.stage3_task('continue',jsonb_build_object('serial',c->'serial'))));return s||jsonb_build_object('_gDualHandled',true);
end $$;
